CREATE TABLE `automation_workers` (`id` VARCHAR(191) NOT NULL, `worker_name` VARCHAR(191) NOT NULL, `api_key_hash` VARCHAR(191) NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'OFFLINE', `last_heartbeat_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `automation_workers_worker_name_key`(`worker_name`), PRIMARY KEY (`id`));
CREATE TABLE `automation_jobs` (`id` VARCHAR(191) NOT NULL, `application_id` VARCHAR(191) NOT NULL, `state` ENUM('QUEUED','STARTING','OPENING_BROWSER','LOGGING_IN','VERIFICATION_REQUIRED','LOGIN_SUBMITTED','REQUESTING_OTP','WAITING_FOR_OTP','OTP_RECEIVED','SUBMITTING_OTP','AUTHENTICATED','UPLOADING_DOCUMENT','DOCUMENT_UPLOADED','CONFIRMING_INFORMATION','SELECTING_MISSION','SELECTING_CENTRE','WAITING_FOR_SLOT','SLOT_FOUND','SELECTING_DATE','DATE_SELECTED','CONTINUING_BOOKING','PREPARING_PAYMENT','PAYMENT_READY','PAUSED','RETRYING','FAILED','CANCELLED','COMPLETED') NOT NULL DEFAULT 'QUEUED', `worker_id` VARCHAR(191) NULL, `claimed_at` DATETIME(3) NULL, `paused_at` DATETIME(3) NULL, `retry_count` INTEGER NOT NULL DEFAULT 0, `last_error_code` VARCHAR(191) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `automation_jobs_state_created_at_idx`(`state`,`created_at`), PRIMARY KEY (`id`));
CREATE TABLE `automation_job_events` (`id` VARCHAR(191) NOT NULL, `job_id` VARCHAR(191) NOT NULL, `state` ENUM('QUEUED','STARTING','OPENING_BROWSER','LOGGING_IN','VERIFICATION_REQUIRED','LOGIN_SUBMITTED','REQUESTING_OTP','WAITING_FOR_OTP','OTP_RECEIVED','SUBMITTING_OTP','AUTHENTICATED','UPLOADING_DOCUMENT','DOCUMENT_UPLOADED','CONFIRMING_INFORMATION','SELECTING_MISSION','SELECTING_CENTRE','WAITING_FOR_SLOT','SLOT_FOUND','SELECTING_DATE','DATE_SELECTED','CONTINUING_BOOKING','PREPARING_PAYMENT','PAYMENT_READY','PAUSED','RETRYING','FAILED','CANCELLED','COMPLETED') NOT NULL, `message` VARCHAR(500) NOT NULL, `diagnostics` JSON NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `automation_job_events_job_id_created_at_idx`(`job_id`,`created_at`), PRIMARY KEY (`id`));
ALTER TABLE `automation_jobs` ADD CONSTRAINT `automation_jobs_application_id_fkey` FOREIGN KEY (`application_id`) REFERENCES `applications`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `automation_jobs` ADD CONSTRAINT `automation_jobs_worker_id_fkey` FOREIGN KEY (`worker_id`) REFERENCES `automation_workers`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `automation_job_events` ADD CONSTRAINT `automation_job_events_job_id_fkey` FOREIGN KEY (`job_id`) REFERENCES `automation_jobs`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
